def check_winner(self):
    """
    Check if there is a winner on the board in rows, columns and diagonals three directions
    :return: str or None, the mark of the winner ('X' or 'O'), or None if there is no winner yet
    """
    num_rows = len(self.board)
    num_cols = len(self.board[0])

    # Check rows
    for row in range(num_rows):
        mark = self.board[row][0]
        if mark != ' ' and all(self.board[row][col] == mark for col in range(num_cols)):
            return mark

    # Check columns
    for col in range(num_cols):
        mark = self.board[0][col]
        if mark != ' ' and all(self.board[row][col] == mark for row in range(num_rows)):
            return mark

    # Check diagonals only if enough space exists
    # Main diagonal: top-left to bottom-right
    if num_rows > 0 and num_cols > 0:
        diag_len = min(num_rows, num_cols)
        if diag_len >= 3:
            mark = self.board[0][0]
            if mark != ' ' and all(self.board[i][i] == mark for i in range(diag_len)):
                return mark

    # Anti-diagonal: top-right to bottom-left
    if num_rows > 0 and num_cols > 0:
        diag_len = min(num_rows, num_cols)
        if diag_len >= 3:
            mark = self.board[0][num_cols - 1]
            if mark != ' ' and all(self.board[i][num_cols - 1 - i] == mark for i in range(diag_len)):
                return mark

    return None

